def solve():
    n = int(input())
    angles = [int(input()) for _ in range(n)]

    def dfs(index, total):
        if index == n:
            return total % 360 == 0

        # Try clockwise (add angle)
        if dfs(index + 1, total + angles[index]):
            return True

        # Try counterclockwise (subtract angle)
        if dfs(index + 1, total - angles[index]):
            return True

        return False

    print("YES" if dfs(0, 0) else "NO")

solve()
"}

