sticks = list(map(int, input().split()))
counts = Counter(sticks)

# Check if we can make a bear or elephant
for length, freq in counts.items():
    if freq >= 4:
        # Use 4 for legs
        remaining = [stick for stick in sticks if stick != length] + [length] * (freq - 4)
        if len(remaining) == 2:
            # Compare the remaining sticks
            if remaining[0] < remaining[1] or remaining[1] < remaining[0]:
                print("Bear")
            elif remaining[0] == remaining[1]:
                print("Elephant")
            else:
                print("Alien")
        else:
            # We have more than 4 of this length, we can still make it
            # Remaining sticks: one of this length and the rest
            print("Bear" if (remaining[0] < remaining[1] or remaining[1] < remaining[0]) else "Elephant")

        exit()

print("Alien")
"}

