import sys
from collections import defaultdict

def solve():
    MOD = 10**9 + 7

    # Read input
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Find all distinct prime factors for each number
    prime_factors = defaultdict(set)
    max_num = max(a)
    for i in range(2, max_num + 1):
        if i in prime_factors:
            continue
        for j in range(i, max_num + 1, i):
            prime_factors[j].add(i)

    # Calculate Möbius function
    mu = {}
    for num in range(1, max_num + 1):
        factors = prime_factors.get(num, set())

        # Check if any factor appears more than once
        has_square = False
        for factor in factors:
            if factor * factor <= num:
                if num % (factor * factor) == 0:
                    has_square = True
                    break
        if has_square:
            mu[num] = 0
        else:
            # If square-free, check number of prime factors
            mu[num] = -1 if len(factors) % 2 else 1

    # Calculate number of subsequences for each possible divisor
    power = [1] * (n + 1)
    for i in range(1, n + 1):
        power[i] = (power[i-1] * 2) % MOD

    result = 0

    # For each possible divisor g
    for g in range(1, max_num + 1):
        # Count elements divisible by g
        cnt = 0
        for num in a:
            if num % g == 0:
                cnt += 1

        f_g = (power[cnt] - 1) % MOD
        result = (result + mu[g] * f_g) % MOD

    return result

print(solve())
"}

