def find_min_number(n):
    if n == 1:
        return -1

    # Start from the smallest n-digit number that ends in 0
    num = 10 ** (n - 1)

    # We need num + k to be divisible by 210
    # Since num ends in 0, we need (num + k) % 21 == 0
    remainder = num % 21
    if remainder == 0:
        result = num
    else:
        k = (21 - remainder)
        result = num + k

    # Ensure result has exactly n digits
    while result >= 10 ** n:
        result += 210

    return str(result)

n = int(input())
print(find_min_number(n))
"}

