def longest_common_subsequence(n, k, permutations):
    # Store positions of each number in each permutation
    positions = [[] for _ in range(n + 1)]

    for perm_idx, perm in enumerate(permutations):
        for num in perm:
            positions[num].append(perm_idx)  # Store the permutation index

    # Sort numbers based on their position in the first permutation
    sorted_numbers = sorted(range(1, n + 1), key=lambda x: positions[x][0])

    # Now find the longest subsequence where each element is after the previous in all k permutations
    dp = [1] * (n + 1)

    for i in range(1, n + 1):
        for j in range(i):
            # Check if number j can come before number i in all permutations
            if all(positions[i][p] > positions[j][p] for p in range(k)):
                dp[i] = max(dp[i], dp[j] + 1)

    return dp[n]

# Read input
n, k = map(int, input().split())
permutations = []

for _ in range(k):
    permutation = list(map(int, input().split()))
    permutations.append(permutation)

# Solve and print result
print(longest_common_subsequence(n, k, permutations))
