import sys
import math

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Get primes up to max element
    max_a = max(a) if a else 1

    # Sieve of smallest prime factor
    spf = list(range(max_a + 1))
    for i in range(2, int(math.sqrt(max_a)) + 1):
        if spf[i] == i:
            for j in range(i * i, max_a + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Map primes to bit positions
    # For simplicity, just use a dictionary to map primes to their positions
    # Actually, let's just use a set representation

    def get_mask(x):
        # Factorize x and create a bitmask where each prime with odd exponent has a bit set
        mask = 0
        while x > 1:
            p = spf[x]
            count = 0
            while x % p == 0:
                x //= p
                count += 1
            if count % 2 == 1:
                mask ^= 1 << p - 2  # map prime 2 to bit 0, prime 3 to bit 1, etc.
        return mask

    # Dictionary to store seen masks and their indices
    seen = {}
    result = -1

    for i, num in enumerate(a):
        mask = get_mask(num)
        if mask == 0:
            # This number itself is a perfect square
            result = 1
            break
        if mask in seen:
            result = i - seen[mask] + 1
            break
        seen[mask] = i

    print(result)

solve()
