result = []

def decide_value(val):
    """Return the optimal value for a single element"""
    if val < 0:
        # Negative number: keep as is (larger absolute value)
        return val
    elif val > 0:
        # Positive number: change to -val - 1 (larger absolute value)
        return -val - 1
    else:
        # Zero: keep as 0 (worse than -1, but needed for product)
        return 0

# Apply decision to all elements
for i, val in enumerate(arr):
    result.append(decide_value(val))

# Now check if we need to adjust for parity (even number of negatives)
# We want the product of signs to be positive
# Count how many negatives we have after applying the above
final_neg = 0
for val in result:
    if val < 0:
        final_neg += 1

# If we have an odd number of negatives, need to change one more element
if final_neg % 2 == 1:
    # Find an element to change to negative
    # Priority: change a positive to negative (if any left)
    # Then change a negative to positive
    # Then change a zero to -1
    for i in range(n):
        if result[i] > 0:
            # Change positive to negative
            result[i] = -result[i] - 1
