def count_sequences(pos, prev_digit, masha):
    if pos == len(masha):
        return 1

    n = len(masha)
    # The current digit of Masha
    a = int(masha[pos])

    # Calculate average and possible next digits
    avg = (a + prev_digit) / 2
    low = int(avg)
    high = int(avg + 1e-9)

    # If average is integer, only one choice
    if low == high:
        return count_sequences(pos + 1, low, masha)
    else:
        # 2 choices: round down or up
        return count_sequences(pos + 1, low, masha) + count_sequences(pos + 1, high, masha)

# Read input
