import math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    # Compute gcd of all a_i modulo k
    # But we need gcd of a_i % k
    g = 0
    for x in a:
        g = math.gcd(g, x % k)

    if g == 0:
        # All a_i are multiples of k, so only sum % k = 0 is possible
        res = [0]
    else:
        # Find all x in [0, k-1] such that x % g == 0
        res = []
        for d in range(k):
            if d % g == 0:
                res.append(d)

    print(len(res))
    if res:
        print(' '.join(map(str, res)))

if __name__ == "__main__":
    solve()
