def count_safe_code_variants(s):
    # Count '?' positions
    wildcard_positions = 0

    # Count letter groups
    letter_groups = set()

    # Process each character
    for ch in s:
        if ch == '?':
            wildcard_positions += 1
        elif ch.isalpha() and ch in "ABCDEFGHIJ":
            letter_groups.add(ch)

    # Count fixed digits
    fixed_digits = set()

    for ch in s:
        if ch.isdigit():
            fixed_digits.add(ch)

    num_fixed = len(fixed_digits)
    num_letters = len(letter_groups)
    num_wildcards = wildcard_positions

    # If there are no fixed digits, we can use any digit for letters and wildcards
    if num_fixed == 0:
        return 10 ** (num_letters + num_wildcards)

    # If there are fixed digits, we need to assign distinct digits to them and to letters
    # But wait, the first character can't be 0 if it's a fixed digit

    # First character check
    first_char = s[0]
    if first_char == '0':
        return 0

    # We need to ensure that the first character is not '0' if it's a fixed digit
    # Actually, the problem says: "The first character of string s doesn't equal to character 0."
    # So we don't need to check again

    # Calculate distinct digit assignments
    if num_fixed + num_letters > 10:
        return 0

    distinct_choices = 1
    for i in range(num_fixed + num_letters):
        distinct_choices *= (10 - i)

    return distinct_choices * (10 ** num_wildcards)

s = input().strip()
print(count_safe_code_variants(s))
