def count_particles(n, k):
    """Count the number of particles produced by a particle with decay age k passing
    through n planes."""

    # Base case: if decay age is 1, no copies are produced
    if k == 1:
        return 1

    # If n >= k: the particle will produce copies at each of the first k-1 planes
    if n >= k:
        # The number of copies produced at each plane i (1-indexed) is 2^{i-1}
        # Total particles = sum of all particles at each plane + 1 (original particle)
        total = 1
        for i in range(1, k):
            particles_at_plane = 2 ** (i - 1)
            total += particles_at_plane
        return total

    # If n < k: the particle will produce copies at each of the first n planes
    # The number of copies produced at each plane i (1-indexed) is 2^{i-1}
    total = 1
    for i in range(1, n + 1):
        particles_at_plane = 2 ** (i - 1)
        total += particles_at_plane
    return total


t = int(input())
results = []
for _ in range(t):
    n, k = map(int, input().split())
    results.append(count_particles(n, k))

# Output results modulo 10^9+7
mod = 1000000007
for res in results:
    print(res % mod)
