        elements = [int(next(it)) for _ in range(c)]
        subsets.append(elements)

    needs_toggled = [0] * (n + 1)  # 0 for even, 1 for odd

    for i in range(1, n + 1):
        if s[i - 1] == '0':
            needs_toggled[i] = 1

    ops = [0] * k

    # Process each lamp from left to right
    for i in range(1, n + 1):
        if needs_toggled[i] == 1:
            # Find a subset that contains i and doesn't affect earlier lamps
            # We can apply any subset that contains i, but we need to ensure it doesn't break earlier lamps
            # If we apply a subset that contains earlier lamps, we might need to undo it later
            found = False
            for j in range(k):
                # We want to apply a subset that contains i but doesn't contain earlier lamps
                # Check if this subset contains i and doesn't contain any lamp < i
                if i in subsets[j]:
                    contains_earlier = any(x < i for x in subsets[j] if x != i)
                    if not contains_earlier:
