def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def factorize(n):
    factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])

    for i in range(n):
        a = int(data[1 + 2*i])
        b = int(data[2 + 2*i])

        fa = factorize(a)
        fb = factorize(b)

        ok = True

        # Check for common primes
        all_primes = set(fa.keys()) | set(fb.keys())
        for p in all_primes:
            ap = fa.get(p, 0)
            bp = fb.get(p, 0)

            if (ap + bp) % 3 != 0:
                ok = False
                break
            x = (2 * ap - bp) / 3
            y = (2 * bp - ap) / 3
            if not x.is_integer() or not y.is_integer() or x < 0 or y < 0:
                ok = False
                break

        if ok:
            print("Yes")
        else:
            print("No")

if __name__ == "__main__":
    solve()
