class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]  # path compression
            x = self.parent[x]
        return x

    def union(self, x, y):
        fx = self.find(x)
        fy = self.find(y)
        if fx != fy:
            self.parent[fx] = fy
            return True
        return False


def solve():
    n, m = map(int, input().split())

    uf = UnionFind(n)

    # Add all edges of weight 1
    for _ in range(m):
        a, b = map(int, input().split())
        a -= 1
        b -= 1
        uf.union(a, b)

    # Count connected components from 0-weight edges
    k = set()
    for i in range(n):
        k.add(uf.find(i))

    # MST weight = number of 1-weight edges used = n - k
    print(len(k) - n)

solve()
"}

