def solve():
    MOD = 10**9 + 7
    n = int(input().strip())
    s = input().strip()

    # Check if s itself is a valid regular bracket sequence
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            print(0)
            return
    if balance != 0:
        print(0)
        return

    m = len(s)
    # DP[i][b][p]: number of ways to build a sequence of length i
    # with balance b and currently matching s at position p (0-based)
    # p=0 means we're not currently matching s
    dp = [[[-1 for _ in range(m+1)] for _ in range(n*2+1)] for _ in range(n*2+1)]

    # Initial state: empty sequence, balance 0, not matching s
    dp[0][0][0] = 1

    # For each length
    for length in range(n*2):
        for balance in range(n*2+1):
            for pos in range(m+1):
                if dp[length][balance][pos] == -1:
                    continue

                # Try adding '(' or ')' if it keeps the sequence valid
                for char in ['(', ')']:
                    new_length = length + 1
                    if char == '(':
                        new_balance = balance + 1
                    else:
                        new_balance = balance - 1

                    # Check if the new sequence is valid
                    if new_balance >= 0:
                        # Update position in s we're matching
                        if pos == 0:
                            # Not matching s, start matching if char matches s[0]
                            if char == s[0]:
                                new_pos = 1
                            else:
                                new_pos = 0
                        else:
                            # Continue matching s
                            if char == s[pos]:
                                new_pos = pos + 1
                            else:
                                new_pos = 0

                        dp[new_length][new_balance][new_pos] = (dp[new_length][new_balance][new_pos] + dp[length][balance][pos]) % MOD

    # Count sequences of length 2n with balance 0 that have matched s at least once
    result = 0
    for pos in range(m+1):
        if pos == 0:
            continue  # didn't match s
        result = (result + dp[2*n][0][pos]) % MOD

    print(result)

solve()
