import sys

def max_rectangle_area(heights):
    stack = []
    max_area = 0
    heights.append(0)  # Add a zero to handle remaining bars in the stack

    for i, h in enumerate(heights):
        while stack and heights[stack[-1]] > h:
            height = heights[stack.pop()]
            width = i if not stack else i - stack[-1] - 1
            max_area = max(max_area, height * width)
        stack.append(i)

    return max_area

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    matrix = []
    for _ in range(n):
        row = next(it)
        matrix.append(row)

    # Count consecutive 1s from left to right for each row
    counts = []
    for i in range(n):
        count = 0
        row = matrix[i]
        for ch in row:
            if ch == '1':
                count += 1
            else:
                count = 0
        counts.append(count)

    # For each row, find the maximum rectangle using histogram approach
    max_area = 0
    for i in range(n):
        # Build histogram from row i up to current row
        # We use a stack approach for each row
        histogram = []
        for j in range(m):
            if i == 0:
                histogram.append(counts[i])
            else:
                histogram.append(min(histogram[-1], counts[i]))

        area = max_rectangle_area(histogram)
        max_area = max(max_area, area)

    print(max_area)

if __name__ == "__main__":
    solve()
