def get_spf(max_limit):
    spf = list(range(max_limit + 1))
    for i in range(2, int(max_limit ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

# Gaussian elimination over GF(2)
def gaussian_elimination(matrix, num_vars):
    rank = 0
    result = [0] * len(matrix)

    for col in range(num_vars):
        pivot_row = None
        for row in range(rank, len(matrix)):
            if matrix[row][col] == 1:
                pivot_row = row
                break

        if pivot_row is not None:
            matrix[rank], matrix[pivot_row] = matrix[pivot_row], matrix[rank]
            for r in range(len(matrix)):
                if r != rank and matrix[r][col] == 1:
                    for c in range(col, num_vars + 1):
                        matrix[r][c] ^= matrix[rank][c]
            result[rank] = matrix[rank][num_vars]  # vector at this position
            rank += 1

    # Check if we found a non-empty subset
    for i in range(rank):
        if result[i] == 1:
            return i + 1  # length of the shortest subset
    return -1

# Read input
n = int(input())
a = list(map(int, input().split()))

# Find maximum prime factor
max_a = max(a)

# Precompute smallest prime factors
spf = get_spf(max(max_a, 1000000))  # Ensure we cover up to 10^6

# Find all distinct primes up to 10^6
distinct_primes = set()
for i in range(2, int(10**6 ** 0.5) + 1):
    if spf[i] == i:
        distinct_primes.add(i)

# Build matrix
num_vars = len(distinct_primes)
matrix = []

for num in a:
    if num == 1:
        # Signature is all zeros
        signature = [0] * (num_vars + 1)
        signature[num_vars] = 1  # vector at this position
        matrix.append(signature)
        continue

    # Get prime factorization
    factorization = {}  # prime -> exponent
    temp = num
    for prime in distinct_primes:
        if prime * prime > temp:
            break
        if temp % prime == 0:
            count = 0
            while temp % prime == 0:
                count += 1
                temp //= prime
            factorization[prime] = count % 2  # parity of exponent

    # Handle remaining prime factor
    if temp > 1:
        # temp could be a prime factor > sqrt(10^6)
        count = 0
        while temp % temp == 0:
            count += 1
            temp //= temp
        factorization[temp] = count % 2

    # Build signature
    signature = [0] * (num_vars + 1)
    for prime in factorization:
        index = list(distinct_primes).index(prime)
        signature[index] = factorization[prime]
    signature[num_vars] = 1  # vector at this position
    matrix.append(signature)

# Solve
result = gaussian_elimination(matrix, num_vars)
print(result if result != -1 else -1)
