def solve():
    a00, a01, a10, a11 = map(int, input().split())

    # a01 and a10 must be equal
    if a01 != a10:
        print("Impossible")
        return

    # Find the length n such that n*(n-1)/2 = a00 + a11 + 2*a01
    total = a00 + a11 + 2*a01

    n = 0
    while True:
        if n*(n-1)//2 == total:
            break
        n += 1

    # Construct the string
    # Start with all '0's
    result = ['0'] * n

    # Convert from the end to '1's to get a11 "11" subsequences
    for i in range(n - 1, -1, -1):
        if a11 > 0:
            result[i] = '1'
            a11 -= 1

    # Convert from the start to '0's to get a00 "00" subsequences
    for i in range(n):
        if a00 > 0:
            result[i] = '0'
            a00 -= 1

    print(''.join(result))

