def longest_common_subsequence(n, k, permutations):
    # Record positions of each number in each permutation
    positions = {}  # key: number, value: list of positions
    for perm_num, perm in enumerate(permutations):
        for num, pos in enumerate(perm):
            if num not in positions:
                positions[num] = [0] * k
            positions[num][perm_num] = pos

    # Sort numbers based on their position in the first permutation
    sorted_numbers = sorted(positions.items(), key=lambda x: x[1][0])

    # Find longest increasing subsequence in the sorted list of k-tuples
    # Using dynamic programming
    dp = [1] * len(sorted_numbers)
    for i in range(len(sorted_numbers)):
        for j in range(i):
            # Check if positions are strictly increasing in all permutations
            if all(sorted_numbers[i][1][p] > sorted_numbers[j][1][p] for p in range(k)):
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

