        if num > max_num:
            max_num = num

    # Count how many numbers are divisible by each number
    count_multiples = {}
    for d in range(1, max_num + 1):
        cnt = 0
        for num in freq:
            if num % d == 0:
                cnt += freq[num]
        count_multiples[d] = cnt

