def main():
    q = int(input())

    # Dictionary to store fees at each node
    fees = {}

    for _ in range(q):
        parts = input().split()
        if parts[0] == '1':
            # Type 1: Increase fees on path from v to u by w
            v = int(parts[1])
            u = int(parts[2])
            w = int(parts[3])

            # Find the path from v to u and add w to each edge
            node = v
            while node != u:
                if node > u:
                    # Edge from node to node//2
                    fees[node] = fees.get(node, 0) + w
                    node //= 2
                else:
                    # Edge from u to u//2
                    fees[u] = fees.get(u, 0) + w
                    u //= 2

        elif parts[0] == '2':
            # Type 2: Query sum of fees on path from v to u
            v = int(parts[1])
            u = int(parts[2])

            # Query the total fee from v to u
            total = 0
            node = v
            while node != u:
                if node > u:
                    # Edge from node to node//2
                    total += fees.get(node, 0)
                    node //= 2
                else:
                    # Edge from u to u//2
                    total += fees.get(u, 0)
                    u //= 2

            print(total)

if __name__ == "__main__":
    main()
