import sys

def solve():
    n = int(sys.stdin.readline())
    if n == 1:
        print(-1)
        return

    # The smallest n-digit number is 10^(n-1)
    x = 10 ** (n - 1)

    # We need to find the smallest multiple of 210 that is >= x
    # 210 = LCM(2, 3, 5, 7)
    remainder = x % 210

    if remainder == 0:
        answer = x
    else:
        answer = x + (210 - remainder)

    print(answer)

