def lcs_length(n, k, permutations):
    # For each element, store its position in each permutation
    positions = [[] for _ in range(n + 1)]
    for perm_idx, perm in enumerate(permutations):
        for elem, pos in enumerate(perm, start=1):
            positions[elem].append(pos)

    # Sort elements by their position in the first permutation
    elements_sorted = sorted(range(1, n + 1), key=lambda x: positions[x][0])

    # DP table where dp[i] is the length of the longest common subsequence ending with element i
    dp = [1] * (n + 1)

    for i in range(n):
        for j in range(i + 1, n + 1):
            # Check if element j can come after element i in all permutations
            valid = True
            for perm_idx in range(k):
                if positions[j][perm_idx] <= positions[i][perm_idx]:
                    valid = False
                    break
            if valid:
                dp[j] = max(dp[j], dp[i] + 1)

    return max(dp)

