def mobius(max_val):
    is_prime = [True] * (max_val + 1)
    min_prime = [0] * (max_val + 1)
    for i in range(2, max_val + 1):
        if is_prime[i]:
            min_prime[i] = i
            for j in range(i * i, max_val + 1, i):
                is_prime[j] = False
                if min_prime[j] == 0:
                    min_prime[j] = i
    mu = [1] * (max_val + 1)
    for i in range(2, max_val + 1):
        if min_prime[i] == i:
            # i is prime
            mu[i] = -1
        else:
            # check if square factor
            p = min_prime[i]
            if i // p % p == 0:
                # has square factor
                mu[i] = 0
            else:
                mu[i] = -mu[i // p]
    return mu

def solve():
    MOD = 10**9 + 7
    n = int(input())
    a = list(map(int, input().split()))

    max_val = max(a)
    freq = [0] * (max_val + 1)
    for x in a:
        freq[x] += 1

    # Compute count of elements divisible by d for all d
    cnt = [0] * (max_val + 1)
    for x in a:
        for d in range(1, int(x**0.5) + 1):
            if x % d == 0:
                cnt[d] += 1
                if d != x // d:
                    cnt[x // d] += 1

    # Compute powers of 2 modulo MOD
    pow2 = [1] * (max_val + 1)
    for i in range(1, max_val + 1):
        pow2[i] = (pow2[i-1] * 2) % MOD

    mu = mobius(max_val)

    result = 0
    for d in range(1, max_val + 1):
        result = (result + mu[d] * (pow2[cnt[d]] - 1)) % MOD

    print(result)

