def solve():
    n = int(input())
    s = input()
    m = len(s)

    # DP1: dp1[i][b] = number of regular sequences of length i with balance b
    dp1 = [[0] * (n + 1) for _ in range(n + 1)]
    dp1[0][0] = 1

    for i in range(n):
        for b in range(n + 1):
            if dp1[i][b] == 0:
                continue

            # Add '('
            if b < n:
                dp1[i+1][b+1] = (dp1[i+1][b+1] + dp1[i][b]) % MOD

            # Add ')'
            if b > 0:
                dp1[i+1][b-1] = (dp1[i+1][b-1] + dp1[i][b]) % MOD

    # DP2: dp2[i][b][pos] = number of sequences of length i, balance b, matching s up to pos
    dp2 = [[[0] * (m + 1) for _ in range(n + 1)] for _ in range(n + 1)]

    dp2[0][0][0] = 1

    for i in range(n):
        for b in range(n + 1):
            for pos in range(m + 1):
                if dp2[i][b][pos] == 0:
                    continue

                # Try adding '('
                if b < n:
                    new_b = b + 1
                    new_pos = pos
                    if pos < m and s[pos] == '(':
                        new_pos = min(pos + 1, m)
                    dp2[i+1][new_b][new_pos] = (dp2[i+1][new_b][new_pos] + dp2[i][b][pos]) % MOD

                # Try adding ')'
                if b > 0:
                    new_b = b - 1
                    new_pos = pos
                    if pos < m and s[pos] == ')':
                        new_pos = min(pos + 1, m)
                    dp2[i+1][new_b][new_pos] = (dp2[i+1][new_b][new_pos] + dp2[i][b][pos]) % MOD

    # The answer is dp2[n][0][m]
    ans = dp2[n][0][m] % MOD

    print(ans)

