import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    sticks = list(map(int, data))

    # Count frequencies
    from collections import Counter
    freq = Counter(sticks)

    # Check if we can make a bear or elephant
    possible_bear = False
    possible_elephant = False

    for length, count in freq.items():
        if count == 4:
            # Check remaining sticks
            remaining = []
            for l, c in freq.items():
                if l != length:
                    remaining.extend([l] * c)

            # Check if we can make a bear
            if len(remaining) == 2:
                if remaining[0] != remaining[1]:  # different lengths
                    possible_bear = True
            elif len(remaining) == 4:
                # Not possible, we only have 6 sticks total
                pass

    # Check if we can make an elephant
    for length, count in freq.items():
        if count == 4:
            # Check remaining sticks
            remaining = []
            for l, c in freq.items():
                if l != length:
                    remaining.extend([l] * c)

            # Check if we can make an elephant
            if len(remaining) == 2:
                if remaining[0] == remaining[1]:  # same length
                    possible_elephant = True

    # Determine output
    if possible_bear:
        print("Bear")
    elif possible_elephant:
        print("Elephant")
    else:
        print("Alien")

if __name__ == "__main__":
    solve()
