import math

def minimal_perimeter(a, b):
    total = a + b
    min_perimeter = float('inf')

    # Find all factor pairs of total
    for i in range(1, int(math.isqrt(total)) + 1):
        if total % i == 0:
            x = i
            y = total // i

            # Check if red can form a rectangle
            red_valid = False
            for p in range(1, int(math.isqrt(a)) + 1):
                if a % p == 0:
                    if p <= x and (a // p) <= y:
                        red_valid = True
                        break

            # Check if blue can form a rectangle
            blue_valid = False
            for r in range(1, int(math.isqrt(b)) + 1):
