                    red_valid = True
                    break

            # Check if blue can form a rectangle
            blue_lower = (b * x) // total
            blue_upper = x
            blue_valid = False

            for r in range(max(1, blue_lower), min(x, blue_upper) + 1):
                if b % r == 0:
                    blue_valid = True
                    break

            if red_valid or blue_valid:
                perimeter = 2 * (x + y)
                if perimeter < min_perimeter:
                    min_perimeter = perimeter

    return min_perimeter

