def solve():
    n = int(input())
    items = []
    for i in range(n):
        ti, di, pi = map(int, input().split())
        items.append((ti, di, pi, i + 1))

    # DP: dp[t] = (max_value, used_items) for total time t
    max_time = 20 * 100  # worst case
    dp = [(-1, []) for _ in range(max_time + 1)]
    dp[0] = (0, [])

    for ti, di, pi, idx in items:
        if ti >= di:
            continue

        # Try to take this item
