import sys

def solve() -> None:
    A = int(sys.stdin.readline())

    # For odd A: N = 4, denominations = [5, 2] (gives 3 ways)
    # For even A: N = 2A - 2, denominations = [1, 2] (gives N+1 ways)
    if A % 2 == 1:
