        items.append((ti, di, pi, i))

    # We'll use a DP approach where dp[v] = (max_value, order)
    # dp[v] means with total time v
    dp = {0: (0, [])}

    for ti, di, pi, idx in items:
        # We need to check all existing states and see if we can add this item
        # First, we create a new dictionary for the updated states
        new_dp = {}

        # Not taking this item
        for total_time, (value, order) in dp.items():
            if total_time not in new_dp or value > new_dp[total_time][0]:
                new_dp[total_time] = (value, order)

        # Taking this item at the end
        for total_time, (value, order) in dp.items():
            new_total_time = total_time + ti
            if ti < di and new_total_time <= di:
