import math

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    n, k = int(data[0]), int(data[1])
    a = list(map(int, data[2:2+n]))

    # Compute remainders modulo k
    remainders = [x % k for x in a]

    # Set of achievable remainders
    achievable = {0}

    for r in remainders:
        if r == 0:
            continue  # doesn't add any new remainders

        # Create a new set for this denomination
        new_achievable = set()

        for s in achievable:
            for m in range(k):
                new_rem = (s + m * r) % k
                new_achievable.add(new_rem)

        achievable = new_achievable

    # Output
    print(len(achievable))
    if achievable:
        print(' '.join(map(str, sorted(achievable))))


if __name__ == "__main__":
    solve()
