import sys
import math

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    n, k = int(data[0]), int(data[1])
    a = list(map(int, data[2:2+n]))

    # Track regular denominators and if we have at least one zero remainder
    regular = []
    has_zero = False

    for x in a:
        r = x % k
        if r == 0:
            has_zero = True
        else:
            d = math.gcd(r, k)
            regular.append(d)

    # If we have at least one zero remainder, we can always get remainder 0
    if has_zero:
        if not regular:
            result = [0]
        else:
            # With regular denominators, we can also get other remainders
            result = []
            g = regular[0]
            for d in regular[1:]:
                g = math.gcd(g, d)
            # Multiples of g modulo k
            for i in range(k):
                if (i * g) % k == 0:
                    result.append(i)
            result = list(set(result))  # remove duplicates
        result.sort()
    else:
        # Only regular denominators, we can't get remainder 0
        result = []
        g = regular[0]
        for d in regular[1:]:
            g = math.gcd(g, d)
        # Multiples of g modulo k
        for i in range(k):
            if (i * g) % k == 0:
                result.append(i)
        result = list(set(result))  # remove duplicates
        result.sort()

