def solve():
    m, k, n, s = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    required = Counter(b)

    if m < k * n:
        print(-1)
        return

    # Try each possible starting position for the workpiece
    for i in range(m - k + 1):
        # We need at least count[b] of each type in the workpiece
        # We can remove flowers from the workpiece, but we need to keep enough

        # Count frequencies in the window
        window = a[i:i+k]
        window_count = Counter(window)

        # Check if we can keep this workpiece valid by removing excess
        valid = True
        for t, cnt in required.items():
            if window_count.get(t, 0) < cnt:
                valid = False
                break

        if not valid:
            continue

        # This window is valid! Try to find an answer

        # We need to keep at least k*n flowers
        # We can keep this window and some extra flowers

        # Keep all flowers in this window
        keep = set(range(i, i + k))

        # Keep additional flowers if needed to reach k*n
        needed = k * n - k

        if needed <= 0:
            # We have enough, remove the rest
            remove = []
            for pos in range(m):
                if pos + 1 not in keep:
                    remove.append(pos + 1)
            print(len(remove))
            print(' '.join(map(str, remove)))
            return
        else:
            # We need more flowers, keep additional flowers from the window that aren't needed for the workpiece

            # Keep flowers that appear in the window but are needed for the required counts
            for t, cnt in required.items():
                # Keep at least cnt of each type
                for j in range(i, i + k):
                    if a[j] == t:
                        keep.add(j)
                        needed -= 1
                        if needed <= 0:
