        # We can transform a[0] to k if there's at least one k in the array
        can_transform_left = True

    # Check if we can transform the last element to k
    can_transform_right = True
    for i in range(n-2, -1, -1):
        if a[i] == k:
            break
        # We can transform a[-1] to k if there's at least one k in the array
        can_transform_right = True

