    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return [x for x in divisors if x > 1]

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    original_sum = sum(a)
    min_total = original_sum

    for i in range(n):
        current = a[i]
        divisors = get_divisors(current)
        for x in divisors:
            # Reduce from machine i by factor x
            reduction = current * (1/x - 1)
            # Try to increase each other machine j
            for j in range(n):
                if j == i:
                    continue
                increase = a[j] * (x - 1)
                change = reduction + increase
                if change < 0:
                    min_total = min(min_total, original_sum + change)

    print(min_total)

solve()
