def can_partition(nums, target):
    """Check if we can partition nums into two subsets with sum target"""
    n = len(nums)

    # DP: dp[i][j] = True if we can achieve sum j using first i elements
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(target + 1):
            if nums[i-1] <= j:
                dp[i][j] = dp[i-1][j] or dp[i-1][j - nums[i-1]]

    return dp[n][target]

