import sys
import math

def is_perfect_cube(x):
    if x <= 0:
        return False
    root = round(x ** (1/3))
    # Check nearby values due to floating point inaccuracy
    for i in range(root - 2, root + 3):
        if i ** 3 == x:
            return i
    return None

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    results = []
    idx = 1

    for _ in range(n):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2

        product = a * b
        # Check if product is a perfect cube
        c = is_perfect_cube(product)

        if c is None:
            results.append("No")
        else:
            # Check if a/c and b/c are integers
            if a % c == 0 and b % c == 0:
                results.append("Yes")
            else:
                results.append("No")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

