import sys

def smallest_prime_factor(n):
    if n % 2 == 0:
        return 2
    if n % 3 == 0:
        return 3
    if n % 5 == 0:
        return 5
    if n % 7 == 0:
        return 7
    for i in range(11, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return n

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n = int(sys.stdin.readline())
        sequence = []

        while n > 1:
            spf = smallest_prime_factor(n)
            sequence.append(spf)
            n //= spf

        print(len(sequence))
        print(' '.join(map(str, sequence)))

if __name__ == "__main__":
    solve()
"}

