def min_perimeter(a, b):

    def get_min_perimeter_for_size(s):

        # Find all divisor pairs of s
        divisors = []
        for i in range(1, int(s**0.5) + 1):
            if s % i == 0:
                divisors.append((i, s // i))

        # Try all possible rectangles that can fit
        min_perimeter = float('inf')

        for w, h in divisors:
            # We need a rectangle of size w x h
            # Find dimensions X and Y such that X * Y = a + b, X >= w, Y >= h

            # The minimum perimeter is achieved when X and Y are as close as possible
            # Let's try both possible orientations

            # Case 1: w <= X and h <= Y
            X = max(w, (a + b + h - 1) // h)
            Y = (a + b + X - 1) // X
            if X * Y == a + b:
                min_perimeter = min(min_perimeter, 2 * (X + Y))

            # Case 2: w <= Y and h <= X (same as case 1, just swap)
            X = max(h, (a + b + w - 1) // w)
            Y = (a + b + X - 1) // X
            if X * Y == a + b:
                min_perimeter = min(min_perimeter, 2 * (X + Y))

        return min_perimeter

    return min(get_min_perimeter_for_size(a), get_min_perimeter_for_size(b))

