def is_valid(mask, pos, n):
    """Check if the elements in mask form a valid common subsequence"""
    # Get the positions of elements in the current mask
    elements = []
    for i in range(n):
        if mask & (1 << i):
            elements.append(i + 1)  # Element values are 1-based

    # Check if positions are increasing for all permutations
    for perm in pos:
        positions = [perm[element] for element in elements]
        # Check if positions are in increasing order
        for i in range(len(positions) - 1):
            if positions[i] >= positions[i + 1]:
                return False
    return True

