for _ in range(k):
    permutation = list(map(int, input().split()))
    position_map = {element: idx for idx, element in enumerate(permutation)}
    pos.append(position_map)

# Dynamic programming with bitmask
dp = [0] * (1 << n)

# Initialize dp for all single-element masks
for i in range(n):
    dp[1 << i] = 1

for mask in range(1, 1 << n):
    if is_valid(mask, pos, n):
