def is_valid(mask, pos, n):
    """Check if the elements in mask form a valid common subsequence"""
    # Get the positions of elements in the current mask
    elements = []
    for i in range(n):
        if mask & (1 << i):
            elements.append(i + 1)  # Element values are 1-based

    # Check if positions are increasing for all permutations
    for perm in pos:
        positions = [perm[element] for element in elements]
        # Check if positions are in increasing order
        for i in range(len(positions) - 1):
            if positions[i] >= positions[i + 1]:
                return False
    return True

# Read input
n, k = map(int, input().split())

# Store positions of each element in each permutation
pos = []
for _ in range(k):
    permutation = list(map(int, input().split()))
    position_map = {element: idx for idx, element in enumerate(permutation)}
    pos.append(position_map)

# Dynamic programming with bitmask
dp = [0] * (1 << n)

# Initialize dp for all single-element masks
for i in range(n):
    dp[1 << i] = 1

for mask in range(1, 1 << n):
    if is_valid(mask, pos, n):
        for i in range(n):
            if not (mask & (1 << i)):
                new_mask = mask | (1 << i)
                if is_valid(new_mask, pos, n):
                    dp[new_mask] = max(dp[new_mask], dp[mask] + 1)

print(max(dp))

