def solve():
    # Read n, m, t
    n, m, t = map(int, input().split())

    # Read the grid
    grid = []
    for _ in range(n):
        row = input().strip()
        grid.append(row)

    # Precompute for each cell: if it will ever change, and at which iteration
    # cell_changes[i][j] = (will_change, first_change_time)
    cell_changes = [[(False, 0) for _ in range(m)] for _ in range(n)]

    for i in range(n):
        for j in range(m):
            # Check if cell (i,j) has any adjacent cells with the same color
            # Adjacent cells are: up, down, left, right
            has_same = False
            if i > 0 and grid[i][j] == grid[i-1][j]:
                has_same = True
            if i < n-1 and grid[i][j] == grid[i+1][j]:
                has_same = True
            if j > 0 and grid[i][j] == grid[i][j-1]:
                has_same = True
            if j < m-1 and grid[i][j] == grid[i][j+1]:
                has_same = True

            # If it has same-color neighbors, it changes once at iteration 1
            # Otherwise, it never changes
            if has_same:
                cell_changes[i][j] = (True, 1)
            else:
                cell_changes[i][j] = (False, 0)

    # Process queries
    for _ in range(t):
        i, j, p = map(int, input().split())
        i -= 1
        j -= 1

        # Get if it changes
        will_change, first_change = cell_changes[i][j]

        if not will_change:
            # Never changes, output initial color
            print(grid[i][j])
        else:
            # If it changes at iteration 1, and p >= 1, it flips
            # After flipping, it never changes again
            if p >= 1:
                print('1' if grid[i][j] == '0' else '0')
            else:
                print(grid[i][j])

solve()
