    print("Alien")
else:
    # Get all sticks
    all_sticks = sticks

    # Remove 4 legs from consideration
    remaining_count = 0
    for i, length in enumerate(all_sticks):
        if length == leg_length:
            remaining_count += 1
            if remaining_count == 4:
                # Mark this one as used for legs
                all_sticks[i] = None
        else:
            # Keep this one
            continue

    # Extract the remaining sticks (not None)
    remaining = [length for length in all_sticks if length is not None]

    # We should have exactly 2 remaining sticks
    if len(remaining) != 2:
        print("Alien")
    else:
        head, body = remaining
        if head < body:
            print("Bear")
        elif head == body:
            print("Elephant")
        else:
            print("Alien")

