import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    if m % n != 0:
        print(-1)
        return

    quotient = m // n

    # Count factors of 2
    a = 0
    while quotient % 2 == 0:
        a += 1
        quotient //= 2

    # Count factors of 3
    b = 0
    while quotient % 3 == 0:
        b += 1
        quotient //= 3

    if quotient == 1:
        print(a + b)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
"}

