    l, r, x = map(int, input().split())

    # Extract the subsegment from positions l to r (1-indexed)
    subsegment = P[l-1:r]

    # Sort the subsegment
    sorted_subsegment = sorted(subsegment)

    # Check if position x remains the same
    if x < l or x > r:
        print("Yes")
    else:
        # Check if P[x-1] is at position (x-l) in the sorted subsegment
        if sorted_subsegment[x - l] == P[x - 1]:
            print("Yes")
        else:
            print("No")
