import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    angles = list(map(int, data[1:1+n]))

    # Try all 2^n combinations of clockwise and counterclockwise
    for mask in range(1 << n):
        total = 0
        for i in range(n):
            if mask & (1 << i):
                total += angles[i]
            else:
                total -= angles[i]

        if total % 360 == 0:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    solve()
"}

